<script setup lang="ts">
import { computed, ref, watch, nextTick } from 'vue'
import EducationMonitoring from './EducationMonitoring.vue'
import type { EducationTarget } from '../education-monitoring'
import { useRoute } from 'vue-router'
import { Download, X, Check, RefreshCw } from 'lucide-vue-next'
import * as XLSX from 'xlsx'
import { educationState as state, stateLabels, clubs, directions, remaining, expiry, createRequest, submitPlan, approvePlan, bindClub, pauseVoucher, cancelVoucher, updateRegistry, schoolEvent, refreshExpiry, transportResult, simulateAttendance, financeEvent, paidFor, ageOn, type Voucher, type Payment } from '../education'
const focusId=ref('')
async function openMonitoring(target:EducationTarget){childId.value=target.childId;tab.value=target.tab;if(target.month)month.value=target.month;focusId.value=target.recordId;await nextTick();document.getElementById('edu-record-'+target.recordId)?.scrollIntoView({behavior:'smooth',block:'center'})}
const route=useRoute()
const childId=ref(state.children[0]!.id),date=ref('2026-11-03'),tab=ref('vouchers'),month=ref('2026-10'),message=ref(''),error=ref('')
const child=computed(()=>state.children.find(c=>c.id===childId.value)!),vouchers=computed(()=>state.vouchers.filter(v=>v.childId===childId.value)),requests=computed(()=>state.requests.filter(r=>r.childId===childId.value)),records=computed(()=>state.monthly.filter(m=>m.month===month.value&&vouchers.value.some(v=>v.id===m.voucherId)))
const travel=computed(()=>transportResult(records.value,child.value.region)),unfinished=computed(()=>vouchers.value.filter(v=>['formed','active','paused'].includes(v.state)).length)
const quantity=ref(1),channel=ref('Ijtimoiy xodim'),purpose=ref<'new'|'replacement'|'renewal'>('new'),previous=ref(''),reason=ref(''),requestOpen=ref(false)
watch(()=>route.query.child,id=>{if(typeof id==='string'&&state.children.some(c=>c.id===id))childId.value=id},{immediate:true})
watch(()=>route.query.month,m=>{if(typeof m==='string'&&/^\d{4}-\d{2}$/.test(m)){month.value=m;tab.value='finance'}},{immediate:true})
watch(childId,()=>{message.value='';error.value=''})
const action=ref<'bind'|'pause'|'cancel'|'school'|null>(null),voucherId=ref(''),clubId=ref('C1'),school=ref('private'),confirmed=ref(false)
const selectedVoucher=computed(()=>vouchers.value.find(v=>v.id===voucherId.value))
const schoolLabels:Record<string,string>={public:'Davlat maktabi',private:'Nodavlat maktab',special:'Ixtisoslashtirilgan agentlik maktabi',graduated:'Maktabni bitirgan',abroad:'Xorijga ketgan',deceased:'Vafot etgan',custody:'JIEMda'}
function run(fn:()=>void,success='Amal saqlandi.'){error.value='';message.value='';try{fn();message.value=success;return true}catch(e){error.value=(e as Error).message;return false}}
function request(){if(run(()=>createRequest(childId.value,quantity.value,date.value,channel.value,previous.value,purpose.value),'Murojaat yaratildi.'))requestOpen.value=false}
function openAction(type:typeof action.value,id=''){error.value='';action.value=type;voucherId.value=id;confirmed.value=false;clubId.value=selectedVoucher.value?.clubId??'C1'}
function perform(){if(!confirmed.value){error.value='Namunaviy amalni tasdiqlang.';return}if(run(()=>{if(action.value==='bind')bindClub(voucherId.value,clubId.value,date.value);if(action.value==='pause')pauseVoucher(voucherId.value,date.value);if(action.value==='cancel')cancelVoucher(voucherId.value,date.value);if(action.value==='school')schoolEvent(childId.value,school.value,date.value)}))action.value=null}
function payment(voucherId:string,type:Payment['type'],amount:number|null,correction=false){if(amount===null){error.value='Hisob yoki davomat talabi aniqlanmagan.';return}const id=`FIN-${voucherId}-${month.value}-${type}`;run(()=>financeEvent({id:correction?id+'-CORR':id,voucherId,month:month.value,type,amount:correction?Math.max(0,amount-10000):amount,date:date.value,...(correction?{supersedes:id}:{})}),'Moliya xabari olindi; takroriy ID ikki marta hisoblanmaydi.')}
const tone=(v:Voucher)=>v.state==='active'?'good':v.state==='paused'?'warning':v.state==='cancelled'?'danger':'neutral'
const cash=(v:number|null)=>v===null?'Ma’lumot olinmagan':v.toLocaleString('uz-UZ')+' so‘m'
function exportData(){const book=XLSX.utils.book_new();const data=vouchers.value.map(v=>({Vaucher:v.id,Bola:child.value.name,JShShIR:child.value.pinfl,Holat:stateLabels[v.state],Togarak:clubs.find(c=>c.id===v.clubId)?.name??'Bog‘lanmagan',Boshlanish:v.start??'Boshlanmagan',Tugash:expiry(v)??'Aniqlanmagan','Qolgan kun':remaining(v,date.value)??'Muddat boshlanmagan',Avvalgi:v.previous??''}));XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(data),'Vaucherlar');XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(records.value.map(m=>({Vaucher:m.voucherId,Oy:m.month,Reja:m.planned,'Faol davr rejasi':m.periodPlanned,Davomat:m.attended,Masofa:m.distance,'Hisoblangan budjet':m.courseBudget,'Vakil ulushi':m.parentShare,'Tolangan budjet':paidFor(m.voucherId,m.month,'course')}))),'Hisoblar');XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet([{Izoh:'NAMUNA — 02.11.2026 texnik talab',Bola:child.value.name,Sana:date.value,Oy:month.value,'Yolkira natijasi':travel.value.reason}]),'Filtrlar');XLSX.writeFile(book,'Qoshimcha_talim_vaucherlari.xlsx')}
</script>
<template>
<EducationMonitoring :date="date" @open="openMonitoring" />
<div class="ed-toolbar"><label>Bola<select v-model="childId" aria-label="Qo‘shimcha ta’lim bolasi"><option v-for="c in state.children" :key="c.id" :value="c.id">{{ c.name }} · {{ c.pinfl }}</option></select></label><label>Voqea / hisob sanasi<input v-model="date" type="date" aria-label="Ta’lim voqeasi sanasi" /></label><button @click="requestOpen=true;error='';previous='';purpose='new'">+ Murojaat</button><button @click="exportData"><Download :size="15" /> Excel</button></div>
<p v-if="message" role="status" class="ed-message good">{{ message }}</p><p v-if="error&&!action&&!requestOpen" role="alert" class="ed-message danger">{{ error }}</p>
<section class="ed-profile"><div><b>{{ child.name }}</b><span>{{ child.pinfl }} · {{ ageOn(child.birth,date) }} yosh · {{ child.region }}</span><small>{{ child.parent }}</small></div><span :class="['ed-tag',child.registry?'good':'warning']">{{ child.registry?'Reyestrda':'Reyestrdan chiqqan' }}</span><span :class="['ed-tag',child.school==='public'?'good':'warning']">{{ schoolLabels[child.school] }}</span><span :class="['ed-tag',unfinished===2?'warning':'neutral']">{{ unfinished }} / 2 vaucher</span></section>
<div class="ed-tabs"><button v-for="t in [{id:'vouchers',name:'Vaucherlar'},{id:'requests',name:'Murojaat va reja'},{id:'finance',name:'Davomat va to‘lovlar'},{id:'sources',name:'Manba xabarlari'}]" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{ t.name }}</button></div>
<template v-if="tab==='vouchers'"><div class="ed-cards"><article v-for="v in vouchers" :key="v.id" :id="'edu-record-'+v.id" :class="['ed-card',{'ed-focused':focusId===v.id}]"><header><b>{{ v.id }}</b><span :class="['ed-tag',tone(v)]">{{ stateLabels[v.state] }}</span></header><h3>{{ clubs.find(c=>c.id===v.clubId)?.name??'To‘garak tanlanmagan' }}</h3><div class="ed-pairs"><div><small>Shakllangan</small><span>{{ v.created }}</span></div><div><small>Shartnoma boshlangan</small><span>{{ v.start??'Boshlanmagan' }}</span></div><div><small>Tugash sanasi</small><span>{{ expiry(v)??(v.state==='paused'?'Muddat to‘xtatilgan':'Belgilanmagan') }}</span></div><div><small>Qolgan muddat</small><b>{{ remaining(v,date)===null?'12 kalendar oy':remaining(v,date)+' kun' }}</b></div></div><p v-if="v.previous">Avvalgi vaucher: {{ v.previous }}</p><div class="ed-actions"><button v-if="['formed','active','paused'].includes(v.state)" @click="openAction('bind',v.id)">{{ v.state==='formed'?'To‘garakka bog‘lash':v.state==='paused'?'Davom ettirish':'To‘garakni almashtirish' }}</button><button v-if="v.state==='active'" @click="openAction('pause',v.id)">Rasmiy chiqish</button><button v-if="['formed','active','paused'].includes(v.state)" class="ed-danger-button" @click="openAction('cancel',v.id)">Bekor qilish</button></div><details><summary>Holatlar va muddat tarixi</summary><p v-for="(h,i) in v.history" :key="i">{{ h }}</p></details></article></div><div class="ed-actions ed-source-actions"><button @click="run(()=>updateRegistry(child.id,!child.registry),'Reyestr holati namunaviy xabar bilan yangilandi.')">Reyestr holati xabari</button><button @click="openAction('school')">Maktab holati xabari</button><button @click="run(()=>refreshExpiry(date),'Muddatlar tekshirildi.')"><RefreshCw :size="14" /> Muddatlarni tekshirish</button></div></template>
<section v-else-if="tab==='requests'" class="ed-panel"><div class="ed-table"><table><thead><tr><th>Murojaat / kanal</th><th>Vaucher soni</th><th>Xodim muddati</th><th>Yettilik muddati</th><th>Holat</th><th></th></tr></thead><tbody><tr v-for="r in requests" :key="r.id" :id="'edu-record-'+r.id" :class="{'ed-focused':focusId===r.id}"><td>{{ r.id }}<p>{{ r.received }} · {{ r.channel }}</p><small>{{ r.purpose==='replacement'?'Qolgan muddatga o‘rnini bosish':r.purpose==='renewal'?'Yangi 12 oyga qayta berish':'Yangi murojaat' }}</small></td><td>{{ r.quantity }}</td><td :class="r.state==='new'&&r.workerDue<date?'ed-red':''">{{ r.workerDue }}</td><td :class="r.state==='submitted'&&r.councilDue!<date?'ed-red':''">{{ r.councilDue??'Yuborilmagan' }}</td><td>{{ {new:'Qabul qilingan',submitted:'Reja tasdiqda',approved:'Tasdiqlangan',returned:'Qayta ishlashga qaytarilgan'}[r.state] }}<p>{{ r.reason }}</p></td><td><button v-if="['new','returned'].includes(r.state)" @click="run(()=>submitPlan(r.id,date),'Reja tasdiqqa yuborildi.')">Rejaga kiritish va yuborish</button><template v-if="r.state==='submitted'"><button @click="run(()=>approvePlan(r.id,date),'Reja tasdiqlandi; vaucherlar yaratildi.')"><Check :size="14" /> Tasdiqlash</button><input v-model="reason" placeholder="Qaytarish sababi" aria-label="Rejani qaytarish sababi" /><button @click="reason.trim()?run(()=>approvePlan(r.id,date,reason),'Reja qaytarildi.'):error='Qaytarish sababini kiriting.'">Qaytarish</button></template></td></tr><tr v-if="!requests.length"><td colspan="6">Murojaatlar yo‘q. Reja tasdig‘idan keyin vaucher yaratiladi.</td></tr></tbody></table></div><details><summary>Ish kunlari hisobi</summary><p>Prototipda shanba va yakshanba chiqarilgan. Rasmiy bayramlar kalendari real tizimda alohida ulanadi.</p></details></section>
<template v-else-if="tab==='finance'"><section class="ed-panel"><div class="ed-toolbar"><label>Hisob oyi<input v-model="month" type="month" /></label><div class="ed-actions"><button @click="run(()=>simulateAttendance(child.id,'full',month),'Kelajak: to‘liq davomat namunasi olindi.')">To‘liq davomat</button><button @click="run(()=>simulateAttendance(child.id,'ninety',month),'Kelajak: 90–99% davomat namunasi olindi.')">90–99% davomat</button><button @click="run(()=>simulateAttendance(child.id,'missed',month),'Kelajak: uzoq to‘garakda yetarli bo‘lmagan davomat.')">Uzoq to‘garakda qatnashmagan</button><button @click="run(()=>simulateAttendance(child.id,'partial',month),'Kelajak: yarim oy 6/12 namunasi olindi.')">Yarim oy 6/12</button></div></div><div class="ed-table"><table><thead><tr><th>Vaucher / to‘garak</th><th>Reja / faol davr / o‘tilgan / qatnashgan</th><th>Masofa</th><th>Budjet hisobi 80%</th><th>Vakil ulushi 20%</th><th>Moliya to‘lovi</th><th></th></tr></thead><tbody><tr v-for="m in records" :key="m.id" :id="'edu-record-'+m.id" :class="{'ed-focused':focusId===m.id}"><td>{{ m.voucherId }}<p>{{ clubs.find(c=>c.id===(m.clubId??vouchers.find(v=>v.id===m.voucherId)?.clubId))?.name }}</p></td><td>{{ m.planned }} / {{ m.periodPlanned }} / {{ m.held }} / {{ m.attended }}</td><td>{{ m.distance }} km<p>{{ m.clubType==='private'?'Nodavlat':'Davlat' }}</p></td><td>{{ cash(m.courseBudget) }}</td><td>{{ cash(m.parentShare) }}</td><td><span :class="['ed-tag',paidFor(m.voucherId,m.month,'course')===null?'warning':'good']">{{ cash(paidFor(m.voucherId,m.month,'course')) }}</span><p v-if="paidFor(m.voucherId,m.month,'course')!==null">Farq: {{ cash(m.courseBudget-paidFor(m.voucherId,m.month,'course')!) }}</p></td><td><button @click="payment(m.voucherId,'course',m.courseBudget)">Moliya javobi</button><button @click="payment(m.voucherId,'course',m.courseBudget,true)">Tuzatish namunasi</button></td></tr><tr v-if="!records.length"><td colspan="7">Tanlangan oy bo‘yicha manba ma’lumoti olinmagan.</td></tr></tbody></table></div></section><section class="ed-panel"><header><h3>Yo‘lkira qoplamasi</h3><span :class="['ed-tag',travel.state==='calculated'?'good':travel.state==='notEligible'?'danger':'warning']">{{ travel.state==='calculated'?'Hisoblangan':travel.state==='notEligible'?'Qoplama sharti bajarilmagan':'Aniqlashtirish kerak' }}</span></header><p>{{ travel.reason }}</p><div class="ed-pairs"><div><small>Tanlangan vaucher</small><b>{{ travel.voucherId??'—' }}</b></div><div><small>Hisoblangan qoplama</small><b>{{ cash(travel.amount) }}</b></div><div><small>Amalda to‘langan</small><b>{{ travel.voucherId?cash(paidFor(travel.voucherId,month,'travel')):'Ma’lumot olinmagan' }}</b></div></div><button v-if="travel.voucherId" :disabled="travel.state!=='calculated'" @click="payment(travel.voucherId!,'travel',travel.amount)">Yo‘lkira bo‘yicha moliya javobi</button><details><summary>Hisob asoslari va kelishilmagan shart</summary><p>Faqat nodavlat to‘garak; Toshkentda &gt;10 km uchun 50% BHM, boshqa hududda &gt;5 km uchun 75% BHM. BHM — namunaviy 400 000 so‘m. Ikkita nodavlat to‘garakda uzoqrog‘i tanlanadi. Uning davomati yetarli bo‘lmasa yaqinrog‘iga o‘tilmaydi.</p><p>И002 27: kamida 90%; keyingi bandlar va qabul mezoni: to‘liq davomat. 90–99% uchun avtomatik summa belgilanmaydi. Bu prototip siyosati kelishilgan huquqiy qaror emas.</p><p>Hisoblash natijalari Kelajak, amaldagi to‘lov moliya manbasi sifatida namoyish qilinadi. Farq avtomatik qarzdorlik deb olinmaydi.</p></details></section></template>
<section v-else class="ed-panel"><h3>Almashinuv tarixi · namuna</h3><p v-for="(item,i) in state.sourceLog" :key="i" class="ed-log">{{ item }}</p><div class="ed-directions"><div v-for="d in directions" :key="d.id"><b>{{ d.name }}</b><span>{{ d.min }}–{{ d.max }} yosh · {{ d.cap }} BHMgacha</span></div></div></section>
<div v-if="requestOpen||action" class="ed-overlay" @click.self="requestOpen=false;action=null" @keydown.esc="requestOpen=false;action=null"><section class="ed-dialog" role="dialog" aria-modal="true" aria-label="Qo‘shimcha ta’lim amali"><header><h3>{{ requestOpen?'Yangi murojaat':action==='bind'?'To‘garak va shartnoma':action==='pause'?'Rasmiy chiqish':action==='cancel'?'Vaucher bekor qilinishi':'Maktab holati xabari' }}</h3><button @click="requestOpen=false;action=null" aria-label="Ta’lim shaklini yopish"><X :size="18" /></button></header><p>{{ child.name }} · {{ child.pinfl }}</p><form v-if="requestOpen" @submit.prevent="request"><label>Vaucher soni<select v-model.number="quantity"><option :value="1">1 ta</option><option :value="2">2 ta</option></select></label><label>Murojaat turi<select v-model="purpose"><option value="new">Yangi vaucher</option><option value="replacement">Bekor qilingan vaucher o‘rniga qolgan muddat</option><option value="renewal">Muddati tugagach yangi 12 oy</option></select></label><label v-if="purpose!=='new'">Avvalgi vaucher<select v-model="previous" required><option value="">Tanlang</option><option v-for="v in vouchers.filter(v=>purpose==='replacement'?v.state==='cancelled':v.state==='expired')" :key="v.id" :value="v.id">{{ v.id }} · {{ stateLabels[v.state] }}</option></select></label><label>Kanal<select v-model="channel"><option>Ijtimoiy xodim</option><option>Inson markazi</option><option>my.gov.uz</option><option>Baraka</option><option>Reyestrga kirishdagi ehtiyoj</option></select></label><label>Kelib tushgan sana<input v-model="date" type="date" required /></label><p v-if="error" role="alert" class="ed-red">{{ error }}</p><button class="ed-primary">Murojaatni saqlash</button></form><form v-else @submit.prevent="perform"><p v-if="selectedVoucher">{{ selectedVoucher.id }} · {{ stateLabels[selectedVoucher.state] }}</p><label v-if="action==='bind'">To‘garak<select v-model="clubId"><option v-for="c in clubs" :key="c.id" :value="c.id">{{ c.name }} · {{ c.type==='private'?'nodavlat':'davlat' }}</option></select></label><label v-if="action==='school'">Ta’lim manbasidagi holat<select v-model="school"><option v-for="(text,key) in schoolLabels" :key="key" :value="key">{{ text }}</option></select></label><label>Voqea sanasi<input v-model="date" type="date" required /></label><label class="ed-checkbox"><input v-model="confirmed" type="checkbox" required /> Namunaviy manba / vakil amali tasdiqlangan</label><p v-if="error" role="alert" class="ed-red">{{ error }}</p><button class="ed-primary">Amalni qo‘llash</button></form></section></div>
</template>
<style scoped src="./education-vouchers.css"></style>
